from .zones import ZONE_FACTORS

BASE = 4.0
PER_KG = 2.5


def shipping_cost(weight_kg, zone):
    """Base fee plus a fee per kilogram, scaled by the zone."""
    return round((BASE + PER_KG * weight_kg) * ZONE_FACTORS[zone], 2)
